import base64
import json


def _validate_records(records):
    if not isinstance(records, list):
        raise ValueError("records must be a list")

    seen_ids = set()
    for record in records:
        if not isinstance(record, dict):
            raise ValueError("each record must be a dict")
        if set(record.keys()) != {"id", "name", "active"}:
            raise ValueError("record must contain exactly id, name, active")

        rid = record["id"]
        if isinstance(rid, bool) or not isinstance(rid, int) or rid <= 0:
            raise ValueError("id must be a positive integer")
        if rid in seen_ids:
            raise ValueError("ids must be unique")
        seen_ids.add(rid)

        name = record["name"]
        if not isinstance(name, str) or not name.strip():
            raise ValueError("name must be a non-empty string after trimming")

        active = record["active"]
        if not isinstance(active, bool):
            raise ValueError("active must be a boolean")


def _validate_limit(limit):
    if isinstance(limit, bool) or not isinstance(limit, int) or not (1 <= limit <= 100):
        raise ValueError("limit must be an integer from 1 through 100")


def _decode_cursor(cursor):
    if cursor is None:
        return 0

    if not isinstance(cursor, str):
        raise ValueError("cursor must be a string")

    try:
        raw = base64.urlsafe_b64decode(cursor.encode("ascii"), validate=True)
    except Exception:
        raise ValueError("malformed cursor")

    try:
        payload = json.loads(raw.decode("utf-8"))
    except Exception:
        raise ValueError("malformed cursor")

    if not isinstance(payload, dict) or set(payload.keys()) != {"last_id"}:
        raise ValueError("malformed cursor")

    last_id = payload["last_id"]
    if isinstance(last_id, bool) or not isinstance(last_id, int) or last_id <= 0:
        raise ValueError("malformed cursor")

    return last_id


def _encode_cursor(last_id):
    payload = json.dumps({"last_id": last_id}, separators=(",", ":"), sort_keys=True)
    encoded = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("ascii")
    return encoded


def list_customers(records, cursor=None, limit=50):
    """Return one page of customers ordered by ascending id."""
    _validate_records(records)
    _validate_limit(limit)
    last_id = _decode_cursor(cursor)

    ordered = sorted(records, key=lambda r: r["id"])
    matching = [r for r in ordered if r["id"] > last_id]

    page = matching[:limit]
    items = [dict(r) for r in page]

    next_cursor = None
    if len(matching) > limit:
        next_cursor = _encode_cursor(page[-1]["id"])

    return {"items": items, "next_cursor": next_cursor}
